messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue

        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        document.body.appendChild(renderer.domElement);

        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const sunLight = new THREE.DirectionalLight(0xffffff, 1);
        sunLight.position.set(10, 20, 10);
        scene.add(sunLight);

        // --- Environment ---
        // Ground (Grass)
        const groundGeo = new THREE.PlaneGeometry(100, 1000);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x228B22 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        scene.add(ground);

        // Track (Road)
        const trackGeo = new THREE.PlaneGeometry(12, 1000);
        const trackMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const track = new THREE.Mesh(trackGeo, trackMat);
        track.rotation.x = -Math.PI / 2;
        track.position.y = 0.01; // Prevent z-fighting
        scene.add(track);

        // Finish Line
        const lineGeo = new THREE.PlaneGeometry(12, 2);
        const lineMat = new THREE.MeshStandardMaterial({ color: 0xffffff });
        const finishLine = new THREE.Mesh(lineGeo, lineMat);
        finishLine.rotation.x = -Math.PI / 2;
        finishLine.position.set(0, 0.02, -200);
        scene.add(finishLine);

        // Checkered pattern for finish line (simple stripes)
        const stripeGeo = new THREE.PlaneGeometry(2, 2);
        const stripeMat = new THREE.MeshStandardMaterial({ color: 0x000000 });
        for(let i = -6; i <= 6; i += 4) {
            const s = new THREE.Mesh(stripeGeo, stripeMat);
            s.rotation.x = -Math.PI / 2;
            s.position.set(i, 0.03, -200);
            scene.add(s);
        }

        // --- Car Builder ---
        function createCar(color) {
            const group = new THREE.Group();

            // Body
            const body = new THREE.Mesh(
                new THREE.BoxGeometry(2, 1, 4),
                new THREE.MeshStandardMaterial({ color: color })
            );
            body.position.y = 0.7;
            group.add(body);

            // Cabin
            const cabin = new THREE.Mesh(
                new THREE.BoxGeometry(1.5, 0.8, 2),
                new THREE.MeshStandardMaterial({ color: 0xcccccc })
            );
            cabin.position.set(0, 1.5, -0.2);
            group.add(cabin);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.4, 0.4, 0.5, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });
            const wheelsPos = [[-1.1, 0.4, 1.2], [1.1, 0.4, 1.2], [-1.1, 0.4, -1.2], [1.1, 0.4, -1.2]];

            wheelsPos.forEach(p => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.rotation.z = Math.PI / 2;
                wheel.position.set(...p);
                group.add(wheel);
            });

            return group;
        }

        const redCar = createCar(0xff0000);
        const blueCar = createCar(0x0000ff);

        redCar.position.set(-3, 0, 0);
        blueCar.position.set(3, 0, 0);

        scene.add(redCar);
        scene.add(blueCar);

        // --- Animation Logic ---
        let distance = 0;
        let raceTime = 0;
        const finishZ = -200;
        const resetZ = 0;

        function animate() {
            requestAnimationFrame(animate);
            raceTime += 0.016; // Approx 60fps

            // Blue car: Constant speed
            const blueSpeed = 0.5;
            blueCar.position.z -= blueSpeed;

            // Red car: Starts slower, then accelerates
            // Acceleration curve: starts at 0.3, ramps up to 0.8
            const redSpeed = 0.3 + Math.min(0.5, raceTime * 0.05);
            redCar.position.z -= redSpeed;

            // Camera follow
            const centerX = (redCar.position.x + blueCar.position.x) / 2;
            const centerZ = (redCar.position.z + blueCar.position.z) / 2;

            camera.position.set(centerX, 8, centerZ + 20);
            camera.lookAt(centerX, 0, centerZ - 10);

            // Reset Loop
            if (redCar.position.z < finishZ || blueCar.position.z < finishZ) {
                // Wait a brief moment after crossing
                if (redCar.position.z < finishZ - 10) {
                    redCar.position.z = resetZ;
                    blueCar.position.z = resetZ;
                    raceTime = 0;
                }
            }

            renderer.render(scene, camera);
        }

        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
```
